package com.taskalarm.engine

import android.content.Context
import android.net.Uri

/**
 * Sounds shipped in the APK (res/raw, generated by scripts/generate-sounds.py). Stored on alarms as the symbolic
 * `builtin:<id>` so resource IDs can change between builds; APK resources stay readable before first unlock.
 */
internal object BuiltinSounds {
  val names = linkedMapOf("beacon" to "Beacon", "pulse" to "Pulse", "chime" to "Chime")
  const val PREFIX = "builtin:"

  fun uri(id: String) = PREFIX + id
  fun isBuiltin(uri: String) = uri.startsWith(PREFIX) && uri.removePrefix(PREFIX) in names

  /** Playable URI for any stored sound reference. */
  fun resolve(context: Context, uri: String): Uri =
    if (isBuiltin(uri)) Uri.parse("android.resource://${context.packageName}/raw/${uri.removePrefix(PREFIX)}") else Uri.parse(uri)

  fun defaultPlaylist(): List<Pair<String, String>> = names.map { (id, name) -> uri(id) to name }
}
